int divide(int dividend, int divisor) {
    boolean negative = (dividend < 0) ^ (divisor < 0);
    int a = Math.abs(dividend), b = Math.abs(divisor);
    int q = 0;
    while (a >= b) {
        int shift = 0;
        while (a >= (b << (shift + 1))) shift++;
        a -= b << shift;
        q += 1 << shift;
    }
    return negative ? -q : q;
}

void xorSwap(int[] arr, int i, int j) {
    arr[i] ^= arr[j];
    arr[j] ^= arr[i];
    arr[i] ^= arr[j];
}
